PROMPT_BASIC = 'import Mathlib\n\nnamespace TuringTask\n\ntheorem pisano_le_six_mul (n : Nat) (hn : 0 < n) :\n    exists k : Nat, 0 < k /\\ k <= 6 * n /\\ Nat.fib k % n = 0 /\\ Nat.fib (k + 1) % n = 1 % n := by\n  sorry\n\ntheorem pisano_eq_six_mul_iff (n : Nat) (hn : 0 < n) :\n    (Nat.fib (6 * n) % n = 0 /\\ Nat.fib (6 * n + 1) % n = 1 % n /\\\n      forall k : Nat, 0 < k -> k < 6 * n ->\n        Not (Nat.fib k % n = 0 /\\ Nat.fib (k + 1) % n = 1 % n)) <->\n      exists j : Nat, 0 < j /\\ n = 2 * 5 ^ j := by\n  sorry\n\ntheorem pisano_eq_self_iff (n : Nat) (hn : 0 < n) :\n    (Nat.fib n % n = 0 /\\ Nat.fib (n + 1) % n = 1 % n /\\\n      forall k : Nat, 0 < k -> k < n ->\n        Not (Nat.fib k % n = 0 /\\ Nat.fib (k + 1) % n = 1 % n)) <->\n      (n = 1 \\/ exists j : Nat, n = 24 * 5 ^ j) := by\n  sorry\n\ntheorem entry_eq_two_mul_iff (n : Nat) (hn : 0 < n) :\n    (Nat.fib (2 * n) % n = 0 /\\ forall k : Nat, 0 < k -> k < 2 * n -> 0 < Nat.fib k % n) <->\n      exists j : Nat, n = 6 * 5 ^ j := by\n  sorry\n\ntheorem entry_eq_self_iff (n : Nat) (hn : 0 < n) :\n    (Nat.fib n % n = 0 /\\ forall k : Nat, 0 < k -> k < n -> 0 < Nat.fib k % n) <->\n      ((exists j : Nat, n = 5 ^ j) \\/ exists j : Nat, n = 12 * 5 ^ j) := by\n  sorry\n\nend TuringTask\n'


def humanize_scan_module():
    here = Path(__file__).resolve().parent
    for cand in [here] + list(here.parents):
        if (cand / "humanize_scan.py").is_file():
            sys.path.insert(0, str(cand))
            import humanize_scan
            return humanize_scan
    raise SystemExit("humanize_scan.py not found in the repository root")


def check():
    for name, text in FILES.items():
        assert hashlib.sha256(text.encode("utf-8")).hexdigest() == SHA256[name], name
    for name, text in TEXTS.items():
        bad = sorted({ch for ch in text if ord(ch) > 127 or (ord(ch) < 32 and ch != "\n")})
        assert not bad, (name, bad)
    for name in ("README.md", "lakefile.toml", "StatementAndAxiomsCheck.lean",
                 "TuringTask/Basic.lean", "lean-toolchain", "TuringTask.lean",
                 "lake-manifest.json"):
        assert all(ord(ch) < 128 for ch in FILES[name]), name
    assert 'path = "/opt/mathlib4"' in FILES["lakefile.toml"]
    assert "git =" not in FILES["lakefile.toml"]
    assert '"dir": "/opt/mathlib4"' in FILES["lake-manifest.json"]
    assert FILES["lean-toolchain"] == "leanprover/lean4:v4.33.0-rc1\n"
    basic = FILES["TuringTask/Basic.lean"]
    assert basic.startswith("import Mathlib\nimport TuringTask.Main\n")
    assert basic.replace("import TuringTask.Main\n", "", 1).count("exact ") == 5
    stripped = re.sub(r"  exact [^\n]*\n", "  sorry\n",
                      basic.replace("import TuringTask.Main\n", "", 1))
    assert stripped == PROMPT_BASIC, "Basic.lean differs from the prompt's file"
    joined = "\n".join(v for k, v in FILES.items() if k.endswith(".lean") and "Check" not in k)
    for word in ("sorry", "admit", "native_decide", "axiom", "set_option", "instance", "unsafe",
                 "implemented_by", "extern", "opaque"):
        assert not re.search(r"(?<![A-Za-z_.])" + word + r"\b", joined), word
    for name, text in FILES.items():
        if name.endswith(".lean"):
            for i, line in enumerate(text.split("\n"), 1):
                assert len(line) <= 100, (name, i)
    rows = TEXTS["task24_rubric.csv"].split("\n")
    assert rows[0] == '"ID","Criterion","Weight"' and len(rows) == 7
    assert not TEXTS["task24_rubric.csv"].endswith("\n")
    for i, row in enumerate(rows[1:], 1):
        assert row.startswith(f'"{i}","') and row.endswith('","1"') and row.count('"') == 6
    banned = ("proves", "derives", "works out", "figures out", "computes", "understood",
              "considered", "recognized", "accounted", "clean", "idiomatic", "elegant", "clear",
              "appropriate", "thorough", "correctly", "robust")
    crit = TEXTS["task24_rubric.txt"].lower()
    for word in banned:
        assert not re.search(r"\b" + word + r"\b", crit), word
    assert len(re.findall(r"\bsound\b", crit)) == 5      # only inside the axiom name Quot.sound
    hs = humanize_scan_module()
    pieces = [("explanation", TEXTS["task24_golden_explanation.txt"])]
    pieces += [("criterion %d" % i, c)
               for i, c in enumerate(TEXTS["task24_rubric.txt"].rstrip("\n").split("\n"), 1)]
    for label, text in pieces:
        errors, warnings = hs.scan(text)
        assert not errors and not warnings, (label, errors, warnings)


def main():
    check()
    here = Path(__file__).resolve().parent
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for name in FILES:
            info = zipfile.ZipInfo(f"{PROJECT}/{name}", date_time=(2026, 10, 13, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o644 << 16
            z.writestr(info, FILES[name].encode("utf-8"))
    (here / "golden_solution.zip").write_bytes(buf.getvalue())
    print("wrote golden_solution.zip", len(buf.getvalue()), "bytes, sha256",
          hashlib.sha256(buf.getvalue()).hexdigest()[:16])
    for name, text in TEXTS.items():
        with open(here / name, "w", encoding="ascii", newline="\n") as fh:
            fh.write(text)
        print("wrote", name, len(text), "chars, ASCII ok")
    lean = [n for n in FILES if n.startswith("TuringTask/")]
    print("Lean lines:", {n: FILES[n].count("\n") for n in lean},
          "total", sum(FILES[n].count("\n") for n in lean))
    print("check passed: sha256, ASCII, statements, forbidden words, CSV, humanize scan 0/0")


if __name__ == "__main__":
    main()
